/* ===== player.js ===== */
(function sisiplusPlayer(global) {
  'use strict';
  const app = global.SisiPlus = global.SisiPlus || {};

  function notify(message) {
    if (global.Lampa && Lampa.Noty) Lampa.Noty.show(message);
    else console.warn('[SisiPlus]', message);
  }

  function openWebPage(url) {
    if (!url) return false;
    try { if (global.Lampa && Lampa.WebView && Lampa.WebView.open) { Lampa.WebView.open(url); return true; } } catch (error) {}
    try { if (global.Lampa && Lampa.Browser && Lampa.Browser.open) { Lampa.Browser.open(url); return true; } } catch (error) {}
    try { if (global.AndroidJS && global.AndroidJS.openUrl) { global.AndroidJS.openUrl(url); return true; } } catch (error) {}
    try { if (global.Android && global.Android.openUrl) { global.Android.openUrl(url); return true; } } catch (error) {}
    try { return Boolean(global.open(url, '_blank')); } catch (error) {}
    return false;
  }

  function chooseDefault(streams) {
    let preferred = '';
    try {
      preferred = Lampa.Storage.field('video_quality_default') || Lampa.Storage.get('video_quality_default', '');
    } catch (error) {}
    if (preferred) {
      const wanted = String(preferred).replace(/p$/i, '');
      const key = Object.keys(streams).find((quality) => quality.replace(/p$/i, '') === wanted);
      if (key) return streams[key];
    }
    const priorities = ['original', 'HLS', '1080p', '720p', '480p', '360p', '240p', 'High', 'Low'];
    for (const key of priorities) if (streams[key]) return streams[key];
    return Object.keys(streams).map((key) => streams[key]).find(Boolean);
  }

  function play(video) {
    const streams = video && video.streams ? video.streams : {};
    const url = chooseDefault(streams);
    if (!url || !global.Lampa || !Lampa.Player) {
      if (video && openWebPage(video.webpageUrl)) return true;
      notify('Прямой поток недоступен. Не удалось открыть и страницу источника.');
      return false;
    }
    const quality = {};
    Object.keys(streams).forEach((key) => { if (streams[key]) quality[key] = streams[key]; });
    const item = {
      title: video.title || 'SisiPlus',
      url,
      quality,
      poster: video.poster || '',
      headers: video.headers || undefined
    };
    try {
      Lampa.Player.play(item);
      Lampa.Player.playlist([item]);
      return true;
    } catch (error) {
      console.error('[SisiPlus:player]', error);
      if (openWebPage(video.webpageUrl)) return true;
      notify('Плеер Lampa не смог открыть поток');
      return false;
    }
  }

  async function playItem(item, adapter) {
    if (!adapter) return false;
    if (app.UI && app.UI.Preview) app.UI.Preview.hide();
    if (global.Lampa && Lampa.Loading) Lampa.Loading.start();
    try {
      return play(await adapter.getVideo(item.id, item));
    } catch (error) {
      console.error(`[SisiPlus:${adapter.id}:video]`, error);
      if (openWebPage(item.webpageUrl)) return true;
      notify(error.message || 'Не удалось получить видео');
      return false;
    } finally {
      if (global.Lampa && Lampa.Loading) Lampa.Loading.stop();
    }
  }

  app.Player = { play, playItem, openWebPage, chooseDefault };
})(window);

/* ===== ui.js ===== */
(function sisiplusUi(global) {
  'use strict';

  const app = global.SisiPlus = global.SisiPlus || {};

  const Preview = (() => {
    let timer = 0;
    let active = null;
    let styleReady = false;

    function injectStyle() {
      if (styleReady || typeof document === 'undefined' || !document.head) return;
      styleReady = true;
      const style = document.createElement('style');
      style.textContent = [
        '.sisiplus-preview{position:absolute;inset:0;overflow:hidden;background:#000;z-index:2;pointer-events:none}',
        '.sisiplus-preview video{width:100%;height:100%;object-fit:cover}',
        '.sisiplus-preview--hidden{display:none}'
      ].join('');
      document.head.appendChild(style);
    }

    function unwrap(target) {
      if (!target) return null;
      if (target.nodeType === 1) return target;
      if (target[0] && target[0].nodeType === 1) return target[0];
      if (typeof target.get === 'function') return target.get(0);
      return null;
    }

    function hide() {
      clearTimeout(timer);
      timer = 0;
      if (!active) return;
      const video = active.querySelector('video');
      if (video) {
        try { video.pause(); } catch (error) {}
        video.removeAttribute('src');
        video.load();
      }
      active.remove();
      active = null;
    }

    function show(target, item) {
      hide();
      const enabled = !app.Settings || app.Settings.get('preview_enabled', true) !== false;
      if (!enabled || !item || !item.preview) return;
      const isAndroid = global.Lampa && Lampa.Platform && typeof Lampa.Platform.is === 'function' &&
        Lampa.Platform.is('android');
      if (isAndroid && app.Settings && app.Settings.get('preview_android', false) !== true) return;
      timer = setTimeout(() => {
        const root = unwrap(target);
        if (!root || root.isConnected === false) return;
        injectStyle();
        if (global.getComputedStyle && getComputedStyle(root).position === 'static') {
          root.style.position = 'relative';
        }
        const container = document.createElement('div');
        container.className = 'sisiplus-preview';
        const video = document.createElement('video');
        video.muted = true;
        video.loop = true;
        video.autoplay = true;
        video.playsInline = true;
        video.preload = 'metadata';
        video.src = item.preview;
        container.appendChild(video);
        root.appendChild(container);
        active = container;
        try {
          const promise = video.play();
          if (promise && typeof promise.catch === 'function') promise.catch(() => hide());
        } catch (error) {
          hide();
        }
      }, 900);
    }

    return { show, hide };
  })();

  function normalizeResult(result, page = 1) {
    if (Array.isArray(result)) return { items: result, page, totalPages: page };
    return {
      items: result.items || [],
      page: result.page || page,
      totalPages: result.totalPages || page
    };
  }

  function toLampaCard(item, adapterId) {
    const card = {
      ...item,
      adapterId,
      source: `sisiplus_${adapterId}`,
      name: item.title || item.name || String(item.id),
      title: item.title || item.name || String(item.id),
      poster: item.poster || item.image || '',
      img: item.poster || item.image || '',
      background_image: item.background || item.poster || item.image || '',
      quality: item.badge || item.quality || ''
    };
    // Lampa 3.x Maker читает события из params.emit. Старые Interaction-компоненты
    // игнорируют это поле и получают обработчики через cardRender/card_events.
    card.params = {
      style: { name: 'collection' },
      emit: {
        onlyEnter(target, data) {
          const selected = data || card;
          app.Player.playItem(selected, app.getAdapter(selected.adapterId));
        },
        onLong(target, data) { showCardMenu(data || card, app.getAdapter(adapterId)); },
        onFocus(target, data) { Preview.show(target, data || card); }
      }
    };
    return card;
  }

  function toCollection(result, adapterId) {
    const data = normalizeResult(result);
    return {
      results: data.items.map((item) => toLampaCard(item, adapterId)),
      page: data.page,
      total_pages: data.totalPages,
      collection: true,
      source: `sisiplus_${adapterId}`,
      params: { items: { mapping: 'grid', cols: 3, align_left: true } }
    };
  }

  function empty(component, error) {
    const message = error && error.message ? error.message : 'Ничего не найдено';
    const view = new Lampa.Empty({ descr: message });
    component.activity.loader(false);
    component.start = view.start.bind(view);
    const body = component.activity.render().find('.activity__body > div')[0];
    if (body) body.appendChild(view.render(true));
    component.activity.toggle();
  }

  function bindCard(card, item, adapter) {
    card.onEnter = () => app.Player.playItem(item, adapter);
    card.onMenu = () => showCardMenu(item, adapter);
    const originalFocus = card.onFocus;
    card.onFocus = (target, data) => {
      if (typeof originalFocus === 'function') originalFocus(target, data);
      Preview.show(target, data || item);
    };
  }

  function showCardMenu(item, adapter) {
    const options = [{ title: 'Открыть страницу источника', webpage: true }];
    if (item.country && adapter) {
      options.push({
        title: `Показать: ${app.AdapterUtils.countryLabel(item.country)}`,
        country: item.country
      });
    }
    Lampa.Select.show({
      title: item.title || item.name || 'SisiPlus',
      items: options,
      onBack: () => Lampa.Controller.toggle('content'),
      onSelect(option) {
        Lampa.Controller.toggle('content');
        if (option.country) {
          Lampa.Activity.push({
            title: `${adapter.getName()} · ${app.AdapterUtils.countryLabel(option.country)}`,
            component: 'sisiplus_list', adapterId: adapter.id, category: 'popular', page: 1,
            filters: { country: option.country }
          });
        } else if (!app.Player.openWebPage(item.webpageUrl)) Lampa.Noty.show('Не удалось открыть страницу');
      }
    });
  }

  async function loadMainLines(adapter) {
    const categories = await adapter.getCategories();
    // На стартовом экране достаточно трёх линий. Это заметно ускоряет открытие
    // источника на слабом Android TV и не провоцирует anti-bot несколькими запросами.
    const lines = await Promise.all(categories.slice(0, 3).map(async (category) => {
      try {
        const data = toCollection(await adapter.getList(category.id, 1), adapter.id);
        return {
          ...data,
          title: category.title,
          category,
          adapterId: adapter.id,
          url: category.id,
          card_events: {
            onEnter(card, item) { app.Player.playItem(item, adapter); },
            onMenu(card, item) { showCardMenu(item, adapter); }
          }
        };
      } catch (error) {
        console.warn(`[SisiPlus:${adapter.id}]`, category.id, error);
        return null;
      }
    }));
    const ready = lines.filter((line) => line && line.results.length);
    if (!ready.length) throw new Error('Источник не вернул доступных моделей');
    return ready;
  }

  function createLegacyMainComponent(object) {
    const component = new Lampa.InteractionMain(object);
    const adapter = app.getAdapter(object.adapterId);

    component.create = function create() {
      this.activity.loader(true);
      loadMainLines(adapter)
        .then((lines) => {
          this.build(lines);
          this.activity.loader(false);
        })
        .catch((error) => empty(this, error));
      return this.render();
    };

    component.onMore = (line) => Lampa.Activity.push({
      title: line.title,
      component: 'sisiplus_list',
      adapterId: adapter.id,
      category: line.category.id,
      page: 2
    });
    component.onAppend = (line) => {
      line.onAppend = (card) => {
        const originalFocus = card.onFocus;
        card.onFocus = (target, item) => {
          if (typeof originalFocus === 'function') originalFocus(target, item);
          Preview.show(target, item);
        };
      };
    };
    return component;
  }

  function createMakerMainComponent(object) {
    const adapter = app.getAdapter(object.adapterId);
    const component = Lampa.Maker.make('Main', object);
    component.use({
      onCreate() {
        loadMainLines(adapter)
          .then((lines) => this.build(lines))
          .catch((error) => {
            console.error('[SisiPlus:ui]', error);
            Lampa.Noty.show(error.message || 'Не удалось загрузить источник');
            this.build([]);
          });
      },
      onInstance(line, data) {
        line.use({
          onMore() {
            Lampa.Activity.push({
              title: data.title,
              component: 'sisiplus_list',
              adapterId: adapter.id,
              category: data.category.id,
              page: 2
            });
          }
        });
      },
      onPause: Preview.hide,
      onStop: Preview.hide,
      onDestroy: Preview.hide
    });
    return component;
  }

  function createMainComponent(object) {
    return Lampa.Maker && typeof Lampa.Maker.make === 'function'
      ? createMakerMainComponent(object)
      : createLegacyMainComponent(object);
  }

  function askSearch(adapter) {
    Lampa.Input.edit({ title: `Поиск — ${adapter.getName()}`, value: '', free: true, nosave: true }, (query) => {
      Lampa.Controller.toggle('content');
      if (!query || !query.trim()) return;
      Lampa.Activity.push({
        title: `Поиск: ${query.trim()}`,
        component: 'sisiplus_list',
        adapterId: adapter.id,
        query: query.trim(),
        page: 1
      });
    });
  }

  function showFilterOptions(adapter, object, filter) {
    const selected = object.filters && object.filters[filter.id] ? object.filters[filter.id] : 'all';
    const options = filter.options.map((option) => ({ ...option, selected: option.id === selected }));
    Lampa.Select.show({
      title: filter.title,
      items: options,
      onBack: () => Lampa.Controller.toggle('content'),
      onSelect(option) {
        Lampa.Controller.toggle('content');
        Lampa.Activity.push({
          ...object,
          title: `${adapter.getName()} · ${option.title}`,
          component: 'sisiplus_list',
          page: 1,
          filters: { ...(object.filters || {}), [filter.id]: option.id }
        });
      }
    });
  }

  function showListMenu(adapter, component, object) {
    Promise.all([adapter.getCategories(), adapter.getFilters(object)]).then(([categories, filters]) => {
      const items = [
        { title: 'Поиск', search: true },
        ...filters.map((filter) => {
          const selected = object.filters && object.filters[filter.id];
          const option = filter.options.find((entry) => entry.id === selected);
          return { title: `${filter.title}: ${option ? option.title : 'Все'}`, filter };
        }),
        ...categories
      ];
      Lampa.Select.show({
        title: adapter.getName(),
        items,
        onBack: () => Lampa.Controller.toggle('content'),
        onSelect: (item) => {
          if (item.search) askSearch(adapter);
          else if (item.filter) showFilterOptions(adapter, object, item.filter);
          else Lampa.Activity.push({
            title: item.title,
            component: 'sisiplus_list',
            adapterId: adapter.id,
            category: item.id,
            page: 1
          });
        }
      });
    }).catch((error) => console.error('[SisiPlus:ui]', error));
  }

  function createLegacyListComponent(object) {
    const component = new Lampa.InteractionCategory(object);
    const adapter = app.getAdapter(object.adapterId);
    const load = (params) => params.query
      ? adapter.search(params.query, params.page || 1, params.filters || {})
      : adapter.getList(params.category, params.page || 1, params.filters || {});

    component.create = function create() {
      this.activity.loader(true);
      Promise.resolve(load(object))
        .then((result) => {
          this.build(toCollection(result, adapter.id));
          this.activity.loader(false);
        })
        .catch((error) => empty(this, error));
    };
    component.nextPageReuest = (params, resolve, reject) => {
      Promise.resolve(load(params)).then((result) => resolve(toCollection(result, adapter.id)), reject);
    };
    component.cardRender = (params, item, card) => bindCard(card, item, adapter);
    component.onRight = () => showListMenu(adapter, component, object);
    return component;
  }

  function createMakerListComponent(object) {
    const adapter = app.getAdapter(object.adapterId);
    const load = (params) => params.query
      ? adapter.search(params.query, params.page || 1, params.filters || {})
      : adapter.getList(params.category, params.page || 1, params.filters || {});
    const component = Lampa.Maker.make('Category', object, (module) => {
      if (Lampa.Maker.module) module.toggle(Lampa.Maker.module('Category').MASK.base, 'Pagination');
    });
    component.use({
      onCreate() {
        Promise.resolve(load(object))
          .then((result) => this.build(toCollection(result, adapter.id)))
          .catch((error) => {
            console.error('[SisiPlus:ui]', error);
            Lampa.Noty.show(error.message || 'Не удалось загрузить список');
            this.build(toCollection([], adapter.id));
          });
      },
      onNext(resolve, reject) {
        Promise.resolve(load(object)).then(
          (result) => resolve(toCollection(result, adapter.id)),
          reject
        );
      },
      onRight() { showListMenu(adapter, component, object); },
      onPause: Preview.hide,
      onStop: Preview.hide,
      onDestroy: Preview.hide
    });
    return component;
  }

  function createListComponent(object) {
    return Lampa.Maker && typeof Lampa.Maker.make === 'function'
      ? createMakerListComponent(object)
      : createLegacyListComponent(object);
  }

  function createSearchSource() {
    return {
      title: 'SisiPlus',
      search(params, complete) {
        Promise.all(app.getAdapters().map(async (adapter) => {
          try {
            const result = normalizeResult(await adapter.search(params.query, 1, {}));
            return result.items.map((item) => toLampaCard(item, adapter.id));
          } catch (error) {
            console.warn(`[SisiPlus:${adapter.id}:search]`, error);
            return [];
          }
        })).then((groups) => complete(groups.flat()));
      },
      onCancel() {},
      onSelect(params, close) {
        if (close) close();
        app.Player.playItem(params.element, app.getAdapter(params.element.adapterId));
      },
      params: {
        lazy: true,
        align_left: true,
        card_events: { onMenu(card, item) { showCardMenu(item, app.getAdapter(item.adapterId)); } }
      }
    };
  }

  app.UI = { createMainComponent, createListComponent, createSearchSource, toLampaCard, Preview };
})(window);

/* ===== settings.js ===== */
(function sisiplusSettings(global) {
  'use strict';

  const app = global.SisiPlus = global.SisiPlus || {};
  const component = 'sisiplus';
  const registeredAdapters = new Set();
  let initialized = false;

  function storageGet(name, fallback) {
    if (global.Lampa && Lampa.Storage) {
      if (typeof Lampa.Storage.field === 'function') {
        const value = Lampa.Storage.field(name);
        if (value !== undefined && value !== null) return value;
      }
      return Lampa.Storage.get(name, fallback);
    }
    return fallback;
  }

  function get(name, fallback) {
    return storageGet(`sisiplus_${name}`, fallback);
  }

  function addParam(param, field) {
    if (!global.Lampa || !Lampa.SettingsApi) return;
    // Lampa registers both `select` and `input` through Params.select().
    // Its input renderer expects values[name] to be a string. If it is left
    // undefined, opening the settings component crashes in update().
    const normalizedParam = Object.assign({}, param);
    if (normalizedParam.type === 'input' && typeof normalizedParam.values !== 'string') {
      normalizedParam.values = '';
    }
    Lampa.SettingsApi.addParam({ component, param: normalizedParam, field });
  }

  function init() {
    if (initialized || !global.Lampa || !Lampa.SettingsApi) return;
    initialized = true;
    Lampa.SettingsApi.addComponent({
      component,
      name: `SisiPlus · v${global.SisiPlusVersion || 'dev'}`,
      icon: '<svg viewBox="0 0 64 64"><path fill="currentColor" d="M8 14h48v8H8zm0 14h30v8H8zm0 14h48v8H8z"/></svg>'
    });

    addParam(
      { name: 'sisiplus_preview_enabled', type: 'trigger', default: true },
      { name: 'Видеопревью', description: 'Показывать беззвучное превью при фокусе на карточке.' }
    );
    addParam(
      { name: 'sisiplus_preview_android', type: 'trigger', default: false },
      { name: 'Превью на Android', description: 'Может повысить нагрузку и расход трафика на ТВ-приставке.' }
    );
    addParam(
      { name: 'sisiplus_proxy_url', type: 'input', default: '' },
      { name: 'Свой CORS-прокси', description: 'Необязательно. Шаблон с {url}, {referer}, {key} или URL-префикс.' }
    );
    addParam(
      { name: 'sisiplus_public_proxy', type: 'trigger', default: true },
      { name: 'Резервный публичный прокси', description: 'Использовать только если прямой/нативный запрос не сработал.' }
    );
    addParam(
      { name: 'sisiplus_proxy_key', type: 'input', default: '1206' },
      { name: 'Ключ прокси', description: 'Ключ резервного или собственного прокси.' }
    );
    addParam(
      { name: 'sisiplus_chaturbate_wm', type: 'input', default: '9cg6A' },
      { name: 'Chaturbate WM', description: 'Affiliate WM для официального списка онлайн-комнат.' }
    );
    addParam(
      {
        name: 'sisiplus_search_pages',
        type: 'select',
        values: { 1: 'быстрый', 3: 'средний', 6: 'глубокий', 12: 'максимальный' },
        default: 3
      },
      { name: 'Глубина поиска', description: 'Большая глубина точнее, но создаёт больше запросов.' }
    );
  }

  function registerAdapter(adapter) {
    if (!initialized || registeredAdapters.has(adapter.id)) return;
    registeredAdapters.add(adapter.id);
    addParam(
      { name: `sisiplus_adapter_${adapter.id}`, type: 'trigger', default: true },
      { name: adapter.getName(), description: 'Показывать этот источник в SisiPlus.' }
    );
  }

  function isAdapterEnabled(id) {
    return get(`adapter_${id}`, true) !== false;
  }

  app.Settings = { init, registerAdapter, get, isAdapterEnabled };
})(window);

/* ===== core.js ===== */
(function sisiplusCore(global) {
  'use strict';

  const app = global.SisiPlus = global.SisiPlus || {};
  const adapters = new Map();
  let booted = false;
  let lampaInitialized = false;

  class Adapter {
    constructor(id) {
      if (!id) throw new Error('Адаптеру требуется уникальный id');
      this.id = id;
    }
    getName() { throw new Error('getName() не реализован'); }
    getCategories() { return Promise.resolve([]); }
    getFilters() { return Promise.resolve([]); }
    search() { return Promise.resolve({ items: [], page: 1, totalPages: 1 }); }
    getList() { return Promise.resolve({ items: [], page: 1, totalPages: 1 }); }
    getVideo() { throw new Error('getVideo() не реализован'); }
  }

  function validateAdapter(adapter) {
    const methods = ['getName', 'getCategories', 'getFilters', 'search', 'getList', 'getVideo'];
    if (!adapter || typeof adapter.id !== 'string') throw new Error('Некорректный адаптер');
    methods.forEach((method) => {
      if (typeof adapter[method] !== 'function') throw new Error(`${adapter.id}: отсутствует ${method}()`);
    });
  }

  function registerAdapter(adapter) {
    validateAdapter(adapter);
    if (adapters.has(adapter.id)) throw new Error(`Адаптер ${adapter.id} уже зарегистрирован`);
    adapters.set(adapter.id, adapter);
    if (app.Settings) app.Settings.registerAdapter(adapter);
    return adapter;
  }

  function getAdapter(id) { return adapters.get(id); }
  function getAdapters() {
    return Array.from(adapters.values()).filter((adapter) =>
      !app.Settings || app.Settings.isAdapterEnabled(adapter.id)
    );
  }

  function notify(message) {
    if (global.Lampa && Lampa.Noty) Lampa.Noty.show(message);
    else console.warn('[SisiPlus]', message);
  }

  function openSource(adapter) {
    Lampa.Activity.push({
      title: adapter.getName(),
      component: 'sisiplus_main',
      adapterId: adapter.id,
      page: 1
    });
  }

  function showSources() {
    const sources = getAdapters().map((adapter) => ({ title: adapter.getName(), adapter }));
    if (!sources.length) {
      notify('Нет подключённых адаптеров');
      return;
    }
    if (sources.length === 1) {
      openSource(sources[0].adapter);
      return;
    }
    Lampa.Select.show({
      title: 'Источники SisiPlus',
      items: sources,
      onSelect: (item) => openSource(item.adapter),
      onBack: () => Lampa.Controller.toggle('menu')
    });
  }

  function addMenuButton() {
    if (Lampa.Menu && typeof Lampa.Menu.addButton === 'function') {
      Lampa.Menu.addButton(
        '<svg viewBox="0 0 64 64"><path fill="currentColor" d="M8 14h48v8H8zm0 14h30v8H8zm0 14h48v8H8z"/></svg>',
        'SisiPlus',
        showSources
      );
      return;
    }

    // Совместимость со старыми сборками Lampa без Menu.addButton.
    const list = document.querySelector('.menu .menu__list');
    if (!list || list.querySelector('[data-action="sisiplus"]')) return;
    const button = document.createElement('li');
    button.className = 'menu__item selector';
    button.dataset.action = 'sisiplus';
    button.innerHTML = '<div class="menu__ico">SP</div><div class="menu__text">SisiPlus</div>';
    button.addEventListener('hover:enter', showSources);
    list.appendChild(button);
  }

  function initLampa() {
    if (lampaInitialized || !global.Lampa) return;
    lampaInitialized = true;
    app.Settings.init();
    adapters.forEach((adapter) => app.Settings.registerAdapter(adapter));
    Lampa.Component.add('sisiplus_main', app.UI.createMainComponent);
    Lampa.Component.add('sisiplus_list', app.UI.createListComponent);
    if (Lampa.Search && typeof Lampa.Search.addSource === 'function') {
      Lampa.Search.addSource(app.UI.createSearchSource());
    }
    addMenuButton();
  }

  function boot() {
    if (booted) return;
    booted = true;
    if (!global.Lampa) {
      console.error('[SisiPlus] Lampa API не найден');
      return;
    }
    if (global.appready) initLampa();
    else Lampa.Listener.follow('app', (event) => event.type === 'ready' && initLampa());
  }

  Object.assign(app, { Adapter, registerAdapter, getAdapter, getAdapters, boot, showSources });
})(window);

/* ===== adapters/live-base.js ===== */
(function sisiplusLiveBase(global) {
  'use strict';
  const app = global.SisiPlus;
  const U = app.AdapterUtils;
  const LIVE_COUNTRIES = ['all', 'ru', 'ua', 'us', 'de', 'fr', 'es', 'it', 'br', 'pl', 'jp', 'in']
    .map((id) => ({ id, title: U.COUNTRY_NAMES[id] }));

  class BongaNetworkAdapter extends app.Adapter {
    constructor(id, config) {
      super(id);
      this.config = config;
      this.models = new Map();
    }
    getName() { return this.config.name; }
    getCategories() {
      return Promise.resolve([
        { id: 'all', title: 'Популярные' }, { id: 'new', title: 'Новые' },
        { id: 'female', title: 'Девушки' }, { id: 'couples', title: 'Пары' },
        { id: 'male', title: 'Парни' }, { id: 'transsexual', title: 'Транс-модели' }
      ]);
    }
    getFilters() { return Promise.resolve([U.countryFilter(LIVE_COUNTRIES)]); }
    async requestModels(category, offset, limit) {
      const url = new URL(`${this.config.host}/tools/listing_v3.php`);
      url.searchParams.set('livetab', category || 'all');
      url.searchParams.set('offset', String(offset || 0));
      url.searchParams.set('limit', String(limit || 72));
      const headers = { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' };
      return app.Api.cached(`${this.id}:${url}`, () => app.Api.siteJson(url.href, {
        referer: `${this.config.host}/`, headers
      }), 20_000);
    }
    mapModel(model) {
      const username = model.username;
      const id = String(username || model.id || '');
      const poster = U.absolute(this.config.host, String(model.thumb_image || '').replace('{ext}', 'jpg'));
      const country = U.normalizeLanguage(model.country || model.lang || '');
      const item = {
        id, title: model.display_name || username, poster, background: poster,
        badge: [model.vq, model.viewers ? `${model.viewers} зр.` : '', country ? U.countryLabel(country) : ''].filter(Boolean).join(' · '),
        webpageUrl: `${this.config.roomBase}/${encodeURIComponent(username)}`,
        country, sourceData: model
      };
      this.models.set(id, model);
      return item;
    }
    async getList(category = 'all', page = 1, filters = {}) {
      const current = Math.max(1, Number(page) || 1);
      const country = filters.country && filters.country !== 'all' ? filters.country : '';
      const limit = country ? Math.min(1200, current * 400) : 72;
      const data = await this.requestModels(category, country ? 0 : (current - 1) * limit, limit);
      let models = data.models || [];
      if (country) models = models.filter((model) => U.normalizeLanguage(model.country || model.lang) === country);
      const start = country ? (current - 1) * 72 : 0;
      return U.result(models.slice(start, start + 72).map((model) => this.mapModel(model)), current,
        country ? (models.length > start + 72 ? current + 1 : current) : Math.max(current, Math.ceil((data.total_count || 0) / limit)));
    }
    async search(query, page = 1, filters = {}) {
      const needle = String(query || '').trim().toLowerCase();
      const country = filters.country && filters.country !== 'all' ? filters.country : '';
      const depth = Math.max(1, Number(app.Settings ? app.Settings.get('search_pages', 3) : 3));
      const found = [];
      for (let index = 0; index < depth; index += 1) {
        const data = await this.requestModels('all', index * 400, 400);
        (data.models || []).forEach((model) => {
          const name = `${model.username || ''} ${model.display_name || ''}`.toLowerCase();
          const matchesCountry = !country || U.normalizeLanguage(model.country || model.lang) === country;
          if (name.includes(needle) && matchesCountry) found.push(model);
        });
        if (found.length >= 72 * page) break;
      }
      const start = (page - 1) * 72;
      return U.result(found.slice(start, start + 72).map((model) => this.mapModel(model)), page, found.length > start + 72 ? page + 1 : page);
    }
    getVideo(id, item = {}) {
      const model = item.sourceData || this.models.get(String(id));
      const username = model ? model.username : id;
      const stream = model && model.esid && username ? this.config.stream(model.esid, username) : '';
      return Promise.resolve({
        title: item.title || username || this.getName(), poster: item.poster || '',
        streams: stream ? { HLS: stream } : {}, webpageUrl: item.webpageUrl || `${this.config.roomBase}/${encodeURIComponent(username)}`,
        headers: { Referer: `${this.config.host}/` }
      });
    }
  }

  app.LiveAdapters = { BongaNetworkAdapter, LIVE_COUNTRIES };
})(window);

/* ===== adapters/pornhub.js ===== */
(function pornhubAdapterModule(global) {
  'use strict';
  const app = global.SisiPlus;
  const U = app.AdapterUtils;
  const SITE = 'https://www.pornhub.com';
  const API = `${SITE}/webmasters/search`;

  class PornhubAdapter extends app.Adapter {
    constructor() { super('pornhub'); this.items = new Map(); }
    getName() { return 'Pornhub'; }
    getCategories() {
      return Promise.resolve([
        { id: 'sort:mostrecent', title: 'Новинки' },
        { id: 'sort:mostviewed', title: 'Популярные' },
        { id: 'sort:rating', title: 'По рейтингу' },
        { id: 'category:russian', title: 'Русские' },
        { id: 'category:amateur', title: 'Любительское' },
        { id: 'category:anal', title: 'Анал' },
        { id: 'category:milf', title: 'MILF' },
        { id: 'category:lesbian', title: 'Лесбиянки' },
        { id: 'category:transgender', title: 'Транс' }
      ]);
    }
    mapVideo(video) {
      const page = U.absolute(SITE, video.url || '');
      const id = String(video.video_id || ((page.match(/viewkey=([^&]+)/) || [])[1]) || page);
      const thumbs = [video.default_thumb, video.thumb].concat((video.thumbs || []).map((item) => item.src));
      const poster = thumbs.find((url) => url && url.includes('hdnea=')) || thumbs.find(Boolean) || '';
      const item = {
        id, title: video.title || id, poster, background: poster,
        badge: [video.duration, video.views ? `${video.views} просм.` : ''].filter(Boolean).join(' · '),
        webpageUrl: page, sourceData: video
      };
      this.items.set(id, item);
      return item;
    }
    async request(query, page, ordering, category) {
      const url = new URL(API);
      url.searchParams.set('search', query || '');
      url.searchParams.set('page', String(page));
      url.searchParams.set('ordering', ordering || 'mostrecent');
      url.searchParams.set('thumbsize', 'medium_hd');
      if (category) url.searchParams.set('category', category);
      const data = await app.Api.cached(`ph:${url}`, () => app.Api.siteJson(url.href, { referer: `${SITE}/` }), 45_000);
      const videos = data.videos || (data.data && data.data.videos) || [];
      return U.result(videos.map((video) => this.mapVideo(video)), page, videos.length >= 20 ? page + 1 : page);
    }
    getList(category = 'sort:mostrecent', page = 1) {
      const parts = String(category).split(':');
      return this.request('', page, parts[0] === 'sort' ? parts[1] : 'mostrecent', parts[0] === 'category' ? parts[1] : '');
    }
    search(query, page = 1) { return this.request(query, page, 'mostrecent', ''); }
    async getVideo(id, item = {}) {
      const card = item.webpageUrl ? item : this.items.get(String(id));
      const pageUrl = card && card.webpageUrl ? card.webpageUrl : `${SITE}/view_video.php?viewkey=${encodeURIComponent(id)}`;
      const html = await app.Api.siteText(pageUrl, { referer: `${SITE}/` });
      const marker = (html.match(/var\s+(flashvars_\d+)\s*=/) || [])[1];
      const flashvars = marker ? U.extractAssignedJson(html, `var ${marker} =`) || U.extractAssignedJson(html, `var ${marker}=`) : null;
      const streams = {};
      ((flashvars && flashvars.mediaDefinitions) || []).forEach((definition) => {
        const source = String(definition.videoUrl || '').replace(/\\\//g, '/');
        if (!source || !definition.quality) return;
        const label = `${definition.quality}p`;
        streams[label] = app.Api.mediaUrl(source, `${SITE}/`, !app.Api.isAndroid());
      });
      return { title: card ? card.title : 'Pornhub', poster: card ? card.poster : '', streams, webpageUrl: pageUrl };
    }
  }
  app.registerAdapter(new PornhubAdapter());
})(window);

